package ca.justinmo.glitch.scan

/**
 * A real, tiny JPEG for the scan screen's previews: 48x32, baseline, 4:2:0.
 *
 * A preview runs on the host, where the app's codec - an .so - is not loaded, so a
 * file cannot be read from disk or encoded; it has to travel in the source. This
 * one is 771 bytes of the standard tables and a gradient, and the screen parses it
 * for real, which is the point: the preview then shows the actual geometry, the
 * actual row readout, the actual sliders and button states rather than the empty
 * state a made-up byte array would produce.
 */
internal fun scanPreviewBytes(): ByteArray =
  ""
    .chunked(2)
    .map { it.toInt(16).toByte() }
    .toByteArray()
